function divisor(left, right) {
    let a = left < 0n ? -left : left;
    let b = right < 0n ? -right : right;
    while (b !== 0n)
        [a, b] = [b, a % b];
    return a;
}
export function rational(numerator, denominator = 1n) {
    if (denominator === 0n)
        throw new Error("Temporal rational denominator must not be zero.");
    const sign = denominator < 0n ? -1n : 1n;
    const normalizedNumerator = numerator * sign;
    const normalizedDenominator = denominator * sign;
    const gcd = divisor(normalizedNumerator, normalizedDenominator);
    return {
        numerator: normalizedNumerator / gcd,
        denominator: normalizedDenominator / gcd,
    };
}
export function add(left, right) {
    return rational(left.numerator * right.denominator + right.numerator * left.denominator, left.denominator * right.denominator);
}
export function compare(left, right) {
    const difference = left.numerator * right.denominator - right.numerator * left.denominator;
    return difference < 0n ? -1 : difference > 0n ? 1 : 0;
}
export function maximum(left, right) {
    return compare(left, right) >= 0 ? left : right;
}
export function minimum(left, right) {
    return compare(left, right) <= 0 ? left : right;
}
function safeInteger(value, label) {
    if (!Number.isSafeInteger(value))
        throw new Error(`${label} must be a safe integer.`);
    return BigInt(value);
}
export function durationInFrames(duration, clock) {
    const frameNumerator = safeInteger(clock.frameRate.numerator, "Clock frame-rate numerator");
    const frameDenominator = safeInteger(clock.frameRate.denominator, "Clock frame-rate denominator");
    switch (duration.unit) {
        case "frames":
            return rational(safeInteger(duration.value, "Frame duration"));
        case "milliseconds":
            return rational(safeInteger(duration.value, "Millisecond duration") * frameNumerator, 1000n * frameDenominator);
        case "seconds": {
            const numerator = safeInteger(duration.numerator, "Second duration numerator");
            const denominator = safeInteger(duration.denominator, "Second duration denominator");
            if (denominator <= 0n)
                throw new Error("Second duration denominator must be positive.");
            return rational(numerator * frameNumerator, denominator * frameDenominator);
        }
    }
}
/** Nearest frame boundary; an exact half lands on the later boundary. Input must be non-negative. */
export function quantizeBoundary(value) {
    if (value.numerator < 0n)
        throw new Error("Cannot quantize a negative clipped frame boundary.");
    const rounded = (value.numerator * 2n + value.denominator) / (value.denominator * 2n);
    if (rounded > BigInt(Number.MAX_SAFE_INTEGER))
        throw new Error("Temporal boundary exceeds safe frame arithmetic.");
    return Number(rounded);
}
